import{_ as a,o,c as t,ag as r}from"./chunks/framework.D7xI0JV8.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),i={name:"faq.md"};function s(n,e,l,h,c,d){return o(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="the-problem-this-solves" tabindex="-1">The Problem This Solves <a class="header-anchor" href="#the-problem-this-solves" aria-label="Permalink to &quot;The Problem This Solves&quot;">​</a></h2><p>Users and integrators need short, decision-ready answers to recurring operational questions without searching across long pages.</p><h2 id="why-this-matters" tabindex="-1">Why This Matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why This Matters&quot;">​</a></h2><p>Fast answers reduce support loops and keep users moving through the correct surface and API flows.</p><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20Q%5BCommon%20question%5D%20--%3E%20A%5BFAQ%20quick%20answer%5D%0A%20%20A%20--%3E%20D%5BDetailed%20doc%20link%5D%0A%20%20D%20--%3E%20R%5BCorrect%20route%20or%20endpoint%5D">flowchart LR
  Q[Common question] --&gt; A[FAQ quick answer]
  A --&gt; D[Detailed doc link]
  D --&gt; R[Correct route or endpoint]</pre><h2 id="who-is-this-for" tabindex="-1">Who is this for? <a class="header-anchor" href="#who-is-this-for" aria-label="Permalink to &quot;Who is this for?&quot;">​</a></h2><p>Users who want privacy-aware DeFi controls, and GATE integrators who need endpoint-level operational surfaces.</p><h2 id="is-the-app-production-or-experimental" tabindex="-1">Is the app production or experimental? <a class="header-anchor" href="#is-the-app-production-or-experimental" aria-label="Permalink to &quot;Is the app production or experimental?&quot;">​</a></h2><p>Both. Core user paths are production-oriented, while specific endpoint families and advanced surfaces are explicitly experimental.</p><h2 id="what-is-the-canonical-agent-url-model-now" tabindex="-1">What is the canonical agent URL model now? <a class="header-anchor" href="#what-is-the-canonical-agent-url-model-now" aria-label="Permalink to &quot;What is the canonical agent URL model now?&quot;">​</a></h2><p>Use <code>/agent?v=vault|trade|brain</code> with optional <code>sub</code> where needed.</p><h2 id="what-is-the-canonical-profile-url-model-now" tabindex="-1">What is the canonical profile URL model now? <a class="header-anchor" href="#what-is-the-canonical-profile-url-model-now" aria-label="Permalink to &quot;What is the canonical profile URL model now?&quot;">​</a></h2><p>Use <code>/profile?tab=trust|reputation|compliance|connections</code>.</p><h2 id="are-old-links-still-supported" tabindex="-1">Are old links still supported? <a class="header-anchor" href="#are-old-links-still-supported" aria-label="Permalink to &quot;Are old links still supported?&quot;">​</a></h2><p>Many legacy links still map for compatibility, but new docs and integrations should not rely on old tab conventions.</p><h2 id="does-every-action-use-exactly-the-same-proof-mode" tabindex="-1">Does every action use exactly the same proof mode? <a class="header-anchor" href="#does-every-action-use-exactly-the-same-proof-mode" aria-label="Permalink to &quot;Does every action use exactly the same proof mode?&quot;">​</a></h2><p>No. Verification behavior is flow-specific. Some actions are strict-gated, some are advisory, and some are wallet-first with reconciliation.</p><h2 id="is-this-legal-or-compliance-advice" tabindex="-1">Is this legal or compliance advice? <a class="header-anchor" href="#is-this-legal-or-compliance-advice" aria-label="Permalink to &quot;Is this legal or compliance advice?&quot;">​</a></h2><p>No. Documentation describes technical behavior only and does not provide legal, tax, or investment advice.</p><h2 id="where-should-integrators-start" tabindex="-1">Where should integrators start? <a class="header-anchor" href="#where-should-integrators-start" aria-label="Permalink to &quot;Where should integrators start?&quot;">​</a></h2><p>Start with <a href="/docs/api-overview.html">API overview</a>, then <a href="/docs/developers.html">Developers</a>, then <a href="/docs/architecture-summary.html">Architecture summary</a>.</p><p>Next: <a href="/docs/troubleshooting.html">Troubleshooting</a> | <a href="/docs/api-overview.html">API overview</a></p>`,23)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
